	@Test
	public void nullableSharedHashVariableMustNotSplitCompatibleRows() throws QueryEvaluationException {
		QueryBindingSet leftRow = new QueryBindingSet();
		leftRow.addBinding("leftOnly", vf.createLiteral("left"));
		QueryBindingSet rightRow = new QueryBindingSet();
		rightRow.addBinding("shared", vf.createLiteral("right"));
		rightRow.addBinding("rightOnly", vf.createLiteral("right"));

		HashJoinIteration iter = new HashJoinIteration(
				new CloseableIteratorIteration<>(List.<BindingSet>of(leftRow).iterator()),
				Set.of("shared"),
				new CloseableIteratorIteration<>(List.<BindingSet>of(rightRow).iterator()),
				Set.of("shared"), false);
		try (iter) {
			assertTrue(iter.hasNext(), "an unbound shared name is compatible with a bound value");
			BindingSet joined = iter.next();
			assertEquals("left", joined.getValue("leftOnly").stringValue());
			assertEquals("right", joined.getValue("shared").stringValue());
			assertEquals("right", joined.getValue("rightOnly").stringValue());
			assertFalse(iter.hasNext());
		}
	}

